#include "unity.h"
#include "header.h"
#include "helpers.h"

// Function declaration for update
void update(node **root, int id, int ct, int wt, int tat);

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_node_nonzero_ct_zero_wt_nonzero_tat(void) {
    // Setup: Build a linked list with at least two nodes.
    // We will update the second node (non-head) with:
    // - ct != 0 (so ptr->CT = ct executes)
    // - wt == 0 (so ptr->WT = wt is skipped)
    // - tat != 0 (so ptr->TAT = tat executes)
    // The path requires the loop to execute and exit (ptr != NULL && ptr->ID != id) -> FOR_EXIT.
    // This means the node to update is not the head, and we traverse until we find it.

    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial state of node with ID 2 (second node)
    node *ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: Update node with ID 2 with ct=100, wt=0, tat=200
    int id_to_update = 2;
    int new_ct = 100;
    int new_wt = 0;   // zero -> should be ignored
    int new_tat = 200;

    update(&root, id_to_update, new_ct, new_wt, new_tat);

    // Verify the update: only CT and TAT should be changed, WT remains 0
    ptr = root;
    while (ptr != NULL && ptr->ID != id_to_update) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);   // wt was zero, so unchanged
    TEST_ASSERT_EQUAL_INT(new_tat, ptr->TAT);

    // Verify other nodes are unchanged
    // Node 1 (head) should still have zeros
    ptr = root;
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Node 3 should still have zeros
    ptr = root->next->next;
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(3, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

